CREATE TABLE inventory_stock(sku_id BIGINT NOT NULL,available_quantity BIGINT UNSIGNED NOT NULL DEFAULT 0,locked_quantity BIGINT UNSIGNED NOT NULL DEFAULT 0,sold_quantity BIGINT UNSIGNED NOT NULL DEFAULT 0,version BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(sku_id),CONSTRAINT chk_inventory_quantities CHECK(available_quantity>=0 AND locked_quantity>=0 AND sold_quantity>=0));
CREATE TABLE inventory_reservation(id BIGINT NOT NULL,request_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,sku_id BIGINT NOT NULL,quantity BIGINT UNSIGNED NOT NULL,reference_type VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,reference_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,expires_at DATETIME(6) NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_inventory_reservation_request(request_id),INDEX idx_inventory_reservation_ref(reference_type,reference_id),INDEX idx_inventory_reservation_expiry(status,expires_at),CONSTRAINT chk_inventory_reservation_qty CHECK(quantity>0));
CREATE TABLE inventory_ledger(id BIGINT NOT NULL,sku_id BIGINT NOT NULL,movement_type VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,available_delta BIGINT NOT NULL,locked_delta BIGINT NOT NULL,sold_delta BIGINT NOT NULL,reference_type VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,reference_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,request_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,occurred_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_inventory_ledger_request_type(request_id,movement_type),INDEX idx_inventory_ledger_sku_time(sku_id,occurred_at));
CREATE TABLE inventory_reconciliation(id BIGINT NOT NULL,sku_id BIGINT NOT NULL,expected_available BIGINT NOT NULL,actual_available BIGINT NOT NULL,difference_quantity BIGINT NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,checked_at DATETIME(6) NOT NULL,PRIMARY KEY(id),INDEX idx_inventory_reconciliation_status_time(status,checked_at));
